import heapq
from collections import defaultdict
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        adj = defaultdict(list)
        for a, b, w in edges:
            adj[b].append((a, w))

        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                nd = d if d > w else w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = 0
        for i in range(n):
            if dist[i] == INF:
                return -1
            if dist[i] > ans:
                ans = dist[i]
        return ans
